namespace UnityMount;

/// <summary>
/// Precomputed libvorbis setup headers (packet type 5) indexed by FMOD FSB5 VORBISDATA CRC32.
/// </summary>
internal static class FmodVorbisHeaders
{
	public readonly record struct HeaderEntry( string Base64Bytes, int SeekBit );

	public static bool TryGet( uint crc32, out byte[] headerBytes, out int seekBit )
	{
		if ( Table.TryGetValue( crc32, out var entry ) )
		{
			headerBytes = Convert.FromBase64String( entry.Base64Bytes );
			seekBit = entry.SeekBit;
			return true;
		}
		headerBytes = null;
		seekBit = 0;
		return false;
	}

	static readonly Dictionary<uint, HeaderEntry> Table = new()
	{
		// Stereo 48kHz (POSTAL: Brain Damaged Master.bank & Player.bank)
		[0x6D39BF3Eu] = new( "", 31169 ),
		// Mono 48kHz (POSTAL: Brain Damaged Master.bank & Player.bank)
		[0xB62AD8DFu] = new( "", 32215 ),
	};
}
